function draw(ctx, state, t) {
  var top = 36;
  var bot = 286;
  var thr = 0.25;
  var beta = state.beta;
  function fmt(v) { return Math.round(v * 100) / 100; }
  var r0 = 2;
  var r1 = 1;
  var r2 = 0;
  var r3 = -1;
  var b = beta;
  var e0 = 0;
  var e1 = 0;
  var e2 = 0;
  var e3 = 0;
  var s = 0;
  var p0 = 0;
  var p1 = 0;
  var p2 = 0;
  var p3 = 0;
  var H = bot - top;
  var ythr = bot - thr * H;
  var gap = 14;
  var bw = (512 - gap * 5) / 4;
  var i = 0;
  var x = 0;
  var hh = 0;
  var pp = 0;
  var win = 0;
  var wmax = -1;
  if (b < 0.1) { b = 0.1; }
  e0 = Math.exp(r0 / b);
  e1 = Math.exp(r1 / b);
  e2 = Math.exp(r2 / b);
  e3 = Math.exp(r3 / b);
  s = e0 + e1 + e2 + e3;
  p0 = e0 / s;
  p1 = e1 / s;
  p2 = e2 / s;
  p3 = e3 / s;
  ctx.clearRect(0, 0, state.w, state.h);
  ctx.fillStyle = "#f6f3ec";
  ctx.fillRect(0, 0, state.w, state.h);
  ctx.strokeStyle = "#1f4b99";
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(48, ythr);
  ctx.lineTo(560, ythr);
  ctx.stroke();
  for (i = 0; i < 4; i++) {
    if (i === 0) { pp = p0; }
    if (i === 1) { pp = p1; }
    if (i === 2) { pp = p2; }
    if (i === 3) { pp = p3; }
    if (pp > wmax) { wmax = pp; win = i; }
    x = 48 + gap + i * (bw + gap);
    hh = pp * H;
    ctx.fillStyle = "#1f4b99";
    if (hh > H) {
      ctx.fillRect(x, top, bw, H);
      ctx.fillStyle = "#c4512c";
      ctx.fillText("clipped", x, top + 16);
    } else {
      ctx.fillRect(x, bot - hh, bw, hh);
    }
  }
  ctx.fillStyle = "#1f4b99";
  ctx.font = "12px sans-serif";
  ctx.fillText("threshold " + fmt(thr), 48, ythr - 8);
  ctx.fillText("beta = " + fmt(b), 48, 318);
  ctx.fillText("winner tok " + fmt(win) + " mass " + fmt(wmax), 300, 318);
  ctx.fillText("toy arXiv 2203.02155", 48, 344);
}
